mapper.select:
select p.P_ID as pId, p.D_ID as dId, p.P_Name as pName, p.P_Code as pCode, p.P_Remark as pRemark, p.P_Sort as pSort, p.P_Status as pStatus, p.P_MDM_NO as pMdmNo, p.P_CreateTime as pCreatetime, p.P_CreateU_Id as pCreateuId, p.P_CreateU_Name as pCreateuName, p.P_Duty as pDuty, d.D_Name as dName from SYS_Position p left join SYS_Department d on p.D_ID=d.D_ID
1=1
and p.P_Status=#{pStatus}
and p.D_ID=#{dId}
and p.P_Name like concat('%',#{pName},'%')
order by p.${sortFiled} ${sortType}
limit #{start},#{size}

select count(*) from SYS_Position p left join SYS_Department d on p.D_ID=d.D_ID
1=1
and p.P_Status=#{pStatus}
and p.D_ID=#{dId}
and p.P_Name like concat('%',#{pName},'%')
